{
  "message": "Below is a concise, ready-to-use template and the exact fields/supporting documents to include when you submit a secure support request to change the email for account 2200. Do not send sensitive documents via regular email — use the official secure upload in the support portal.",
  "account_id": "2200",
  "required_request_fields": [
    {
      "field": "Request type",
      "description": "Clear title, e.g. “Request to change account email (Account ID 2200)”",
      "example": "Request to change account email (Account ID 2200)"
    },
    {
      "field": "Account ID",
      "description": "Numeric account identifier",
      "example": "2200"
    },
    {
      "field": "Account owner full name",
      "description": "Exactly as shown on the account",
      "example": "Alex Johnson"
    },
    {
      "field": "Current email on file",
      "description": "The email currently associated with the account (if known)",
      "example": "alex@example.com"
    },
    {
      "field": "Requested new email",
      "description": "The email address you want associated with the account",
      "example": "alex.new@example.org"
    },
    {
      "field": "Primary phone number on file",
      "description": "Phone number currently on file (if known)",
      "example": "+1-555-555-0123"
    },
    {
      "field": "Relationship to account",
      "description": "Owner, authorized agent, admin, etc.",
      "example": "Authorized agent (with signed authorization letter attached)"
    },
    {
      "field": "Reason for change",
      "description": "Brief explanation why the email must be changed (loss of access, compromised email, etc.)",
      "example": "Owner no longer has access to the old email after company reorg"
    },
    {
      "field": "Preferred contact method for verification/response",
      "description": "Indicate whether you want an email reply to the new email after verification, or phone call to listed number",
      "example": "Reply via phone to +1-555-555-0123"
    }
  ],
  "required_documents": [
    {
      "document": "Government-issued photo ID",
      "notes": "Passport or driver’s license; include both front and back if applicable"
    },
    {
      "document": "Proof of address",
      "notes": "Utility bill, bank statement, or similar dated within the last 3 months"
    },
    {
      "document": "Signed authorization letter (if requester is not the owner)",
      "notes": "Must be signed by the account owner and include the owner’s name, account ID, explicit authorization text, requester name, and date"
    }
  ],
  "file_requirements": {
    "formats": ["PDF", "PNG", "JPG/JPEG"],
    "max_size_per_file": "10 MB (or portal limit)",
    "naming_convention": "account2200_ID_lastname_firstname.pdf (example)",
    "security_note": "Use the support portal’s secure upload; do not send unencrypted attachments via regular email."
  },
  "authorization_letter_template": "I, [Account Owner Full Name], account ID [2200], hereby authorize [Requester Full Name] to act on my behalf to request and approve changes to the contact email for this account. I request that the account email be changed from [current.email@example.com] to [new.email@example.com].\n\nAccount Owner Name: [Account Owner Full Name]\nAccount ID: 2200\nRequester Name: [Requester Full Name]\nRequester Relationship: [e.g., Authorized Agent]\nReason for Authorization: [brief reason]\nDate: [YYYY-MM-DD]\nSignature: ___________________________\n(Printed name below signature: ___________________)\n\nAttach a scan/photo of the account owner’s government-issued photo ID and proof of address with this letter.",
  "submission_example_body": "Hello Support Team,\n\nPlease process an email change for account ID 2200. Details below:\n- Account owner: Alex Johnson\n- Current email on file: alex@example.com\n- Requested new email: alex.new@example.org\n- Relationship of requester: Authorized agent (authorization letter attached)\n- Reason: Owner no longer has access to old email\n- Preferred contact: Phone +1-555-555-0123\n\nAttached: signed authorization letter, owner photo ID, proof of address.\n\nThank you,\n[Requester Full Name]",
  "next_steps_and_timeline": {
    "submit": "Upload the request and attachments via the support portal’s secure upload.",
    "acknowledgement": "You should receive an automated acknowledgement within minutes.",
    "manual_review": "Support will manually review documents—typical processing is 2–5 business days; times may vary.",
    "follow_up": "Support may request additional verification or a notarized signature for certain cases."
  },
  "offer": "If you’d like, I can also (a) produce a shortened one-page PDF checklist you can copy into the portal, or (b) review your draft request/authorization letter before you upload it. Which would you prefer?"
}

